<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait ConsentPurposeTenantAccessor
{
    private ConsentPurposeTenantVO $_tenant;
    public function getTenant(): TenantRef
    {
        return $this->_tenant->value();
    }
    public function tenant(): ConsentPurposeTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(ConsentPurposeTenantVO|TenantRef $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = ConsentPurposeTenantVO::from($tenant);
        return $copy;
    }
}
